(function(){var n;function c(){var e=window.AAArt||{},i=window.AARoutes||{},u=e.ART,d=e.LEAD,t=e.H3,h=e.artNote,y=e.artLink,E=e.artInsightLink,R=e.DeadlinesRoadmap,A=e.SBRRoadmap,b=e.FiveCornerDiagram,w=e.EInvoiceCTA,v=e.EInvoiceGuideLinks,m=i.pathForPage,p=i.pathForInsight,x=i.INSIGHTS;function f({onNav:s}){const l=(a,r)=>React.createElement("a",{href:m(a),onClick:o=>{o.preventDefault(),s(a)},style:{color:"var(--aa-cyan)",fontWeight:600,textDecoration:"none"}},r),g=(a,r)=>React.createElement("a",{href:p(a),onClick:o=>{o.preventDefault(),s("insight",a)},style:{color:"var(--aa-cyan)",fontWeight:600,textDecoration:"none"}},r);return React.createElement("div",{className:"container",style:u},React.createElement("p",{style:d},"Small Business Relief now runs to tax periods ending on or before 31\xA0December\xA02029. The condition attached to it did not move: revenue of ",React.createElement("strong",null,"AED\xA03\xA0million or less")," in the relevant tax period ",React.createElement("em",null,"and")," in every previous one. The FTA\u2019s own guide puts the burden plainly \u2014 an electing business \u201Cmust be able to provide evidence to the FTA that their Revenue did not exceed the Small Business Relief threshold for all relevant Tax Periods\u201D. Three more years of relief is three more years of evidence."),React.createElement("h3",{style:t},"Count your periods before you count your revenue"),React.createElement("p",null,"\u201CEvery previous period\u201D sounds alarming until you work out how many you actually have. Corporate Tax applies to tax periods commencing on or after ",React.createElement("strong",null,"1\xA0June\xA02023"),", so trading history before that is irrelevant to this test. What matters is your financial year-end."),React.createElement("p",null,"A December year-end business has its first tax period in 2024, so by the time it files for 2026 it is evidencing three periods. A 31\xA0March year-end started earlier, with a first period ending 31\xA0March\xA02024. A company incorporated in 2025 has ",React.createElement("em",null,"one")," period to evidence, not three. Establish the count first \u2014 a surprising number of eligibility arguments fall apart because someone tested the wrong years."),React.createElement("h3",{style:t},"The first-period trap: nothing is pro-rated"),React.createElement("p",null,"This is the most expensive arithmetic error we see, and it runs in both directions. The FTA\u2019s public clarification on first tax periods states it without hedging: ",React.createElement("em",null,"\u201CWhere the first Tax Period is longer or shorter than a 12-month period, there is no pro-rating of the various thresholds prescribed under the Corporate Tax Law, for example the Revenue threshold for Small Business Relief.\u201D")),React.createElement("p",null,"So a seven-month first period still gets the full AED\xA03\xA0million \u2014 businesses routinely and needlessly disqualify themselves by scaling it down to AED\xA01.75\xA0million. And an eighteen-month first period also gets AED\xA03\xA0million, ",React.createElement("strong",null,"not")," AED\xA04.5\xA0million. Since a UAE company\u2019s first financial year can run anywhere from six to eighteen months, the year-end chosen at incorporation is quietly a Small Business Relief decision."),React.createElement("h3",{style:t},"What \u201Crevenue\u201D catches that your sales ledger will not"),React.createElement("p",null,"The test is ",React.createElement("strong",null,"revenue"),", not profit \u2014 gross, top-line, before a single cost. The working formula is simply ",React.createElement("em",null,"sales plus other income"),", and \u201Cother income\u201D is where eligibility usually dies:"),React.createElement("ul",null,React.createElement("li",null,React.createElement("strong",null,"Asset disposals count at their proceeds, not their gain.")," The FTA\u2019s own worked example has a business sell a shop for AED\xA01.2\xA0million and cross the line at AED\xA04,150,000 of revenue \u2014 permanently, on a transaction that may have made no profit at all."),React.createElement("li",null,React.createElement("strong",null,"Exempt income still counts as revenue.")," A UAE dividend is exempt from Corporate Tax and still lands in the revenue figure for this test."),React.createElement("li",null,React.createElement("strong",null,"Foreign income counts")," for a UAE company, wherever it arose."),React.createElement("li",null,React.createElement("strong",null,"Barter and related-party dealings")," are measured at market value, at arm\u2019s length."),React.createElement("li",null,React.createElement("strong",null,"Output VAT is excluded")," \u2014 it was never your revenue.")),React.createElement("p",null,"A one-off disposal in year two is the classic way a business that trades comfortably under AED\xA03\xA0million loses the relief for good."),React.createElement("h3",{style:t},"Your VAT returns will not agree, and forcing them to is the mistake"),React.createElement("p",null,"Corporate Tax revenue and VAT-declared supplies are different measures and will differ legitimately \u2014 output VAT, dividends, disposal proceeds, foreign income, cash-basis timing, and mismatched period boundaries all pull them apart. The discipline is not to make the two numbers match. It is to hold a short written reconciliation explaining ",React.createElement("em",null,"why")," they differ, prepared while you still remember."),React.createElement("p",null,"We have not seen anything from the FTA describing an automated cross-check between the two, and we would not tell you there is one. The reason to keep the reconciliation is simpler: a tax audit is notified only ten business days in advance, and under the Tax Procedures Law the burden of proving the accuracy of your return sits with ",React.createElement("em",null,"you"),", not with the Authority."),React.createElement("h3",{style:t},"The evidence file the law actually asks for"),React.createElement("p",null,"Here is the part almost every summary misses. The FTA\u2019s relief guide offers an illustrative list \u2014 bank statements, sales ledgers, till rolls \u2014 and says explicitly that the Corporate Tax record rules sit ",React.createElement("em",null,"on top of")," the Tax Procedures Law. That underlying regulation is binding, and it asks for more."),React.createElement("p",null,React.createElement("strong",null,"Cabinet Decision No.\xA074 of 2023")," requires every business to keep, as a minimum, a balance sheet and profit-and-loss account, a ",React.createElement("strong",null,"fixed asset register"),", a wages and salaries register, and inventory records. And then the clause nobody quotes: documents recording ",React.createElement("em",null,"\u201Cany election, assessment, determination or calculation made\u2026 including the basis, or method of assessment, determination or calculation made.\u201D")),React.createElement("p",null,"Read that against Small Business Relief and it is unambiguous. The election is an election. The AED\xA03\xA0million test is a calculation. So the law requires you to keep, for every period, a record that the election was made ",React.createElement("em",null,"and")," a note of how you computed revenue \u2014 which accounting basis, what you included, what you left out. A clean sales ledger with no written basis behind it does not discharge that."),React.createElement("p",null,"The fixed asset register earns its place too: it is precisely the document that evidences the disposal proceeds most likely to have broken the threshold."),React.createElement("p",null,"Below AED\xA03\xA0million you may prepare accounts on the cash basis rather than accrual \u2014 a real choice, and one the FTA can challenge if the outcome is unreasonable. Because the regulation requires the basis to be recorded, switching it in the one year you would otherwise breach is both visible and challengeable. Write down the commercial reason at the time, not afterwards."),React.createElement("h3",{style:t},"Seven years, not five"),React.createElement("p",null,"You will read \u201Cfive years\u201D in a lot of places. For Corporate Tax it is wrong. The Tax Procedures regulation sets five years ",React.createElement("em",null,"\u201Cunless the Tax Law states otherwise\u201D")," \u2014 and the Corporate Tax Law states otherwise, at ",React.createElement("strong",null,"seven years"),", expressly overriding it. Five is right for VAT and Excise, not for this."),React.createElement("p",null,"The clock runs from the period the records relate to, and it extends: four further years if you are in dispute with the FTA, under audit, or were notified of an intended audit before the base period expired. Copies are acceptable instead of originals \u2014 but only if you can reproduce a legible copy within the period the FTA specifies, which can be as little as five business days. A lapsed accounting subscription or an unindexed folder of scans does not meet that standard."),React.createElement("p",null,"With the relief now running to 2029, the last electing period has to be evidenced into the mid-2030s. This is a decade-long filing discipline, not a year-end task."),React.createElement("h3",{style:t},"If you own more than one company"),React.createElement("p",null,"First separate two situations that get muddled. A sole establishment holding three licences is ",React.createElement("strong",null,"one taxable person"),": you add the revenue together and file once. No anti-abuse analysis is needed \u2014 only arithmetic. Three separate LLCs are three taxable persons, and there is exactly one route by which the FTA can treat them as one for this purpose: ",React.createElement("strong",null,"Article\xA06 of Ministerial Decision No.\xA073 of 2023"),", the artificial-separation rule. (Much of the commentary online cites Article\xA05 for this. Article\xA05 is the interest limitation rule.)"),React.createElement("p",null,"The FTA is careful to protect legitimate structures, and says so: ",React.createElement("em",null,"\u201CThere are legitimate circumstances in which a Business may separate its activities or choose to operate through separate entities.\u201D")," Its own worked example of a franchised second cafe \u2014 same name, same branding, same supplier, customers unable to tell them apart \u2014 is ",React.createElement("strong",null,"not")," artificial separation, because the ownership is genuinely different. The distinguishing question is ownership and commercial substance, not whether the shopfronts look alike."),React.createElement("p",null,"Where it turns serious is intent. The Tax Procedures Law defines deliberately understating your revenue, or failing to consolidate related businesses in order to stay below a threshold, as ",React.createElement("strong",null,"tax evasion")," \u2014 a criminal matter, not an administrative one. We are not aware of any published FTA statement applying that provision to Small Business Relief by name, and we would not claim otherwise. But the direction of travel is not ambiguous, and \u201Cwe split it to stay under three million\u201D is not a sentence to say out loud."),React.createElement("h3",{style:t},"What to do this month"),React.createElement("ul",null,React.createElement("li",null,React.createElement("strong",null,"List your tax periods")," from your first one commencing on or after 1\xA0June\xA02023, and put the revenue figure against each."),React.createElement("li",null,React.createElement("strong",null,"Rebuild each figure as sales plus other income"),", adding back disposal proceeds, dividends and foreign income. This is where breaches surface."),React.createElement("li",null,React.createElement("strong",null,"Write the basis note")," \u2014 one paragraph per period on how the figure was computed. The regulation asks for it and almost nobody has it."),React.createElement("li",null,React.createElement("strong",null,"Check the fixed asset register")," for any disposal in a period you claimed."),React.createElement("li",null,React.createElement("strong",null,"If you find a breach in a period you already elected"),", deal with it deliberately. The duty to correct is clear; the route runs through voluntary disclosure, and correcting before the FTA notifies an audit is materially better than after. Take advice on the mechanics before touching the filing.")),h("Sources: Ministerial Decision No. 131 of 2026 (the 2029 date); Ministerial Decision No. 73 of 2023; Federal Decree-Law No. 47 of 2022; Federal Decree-Law No. 28 of 2022 on Tax Procedures and Cabinet Decision No. 74 of 2023; FTA Corporate Tax Guide CTGSBR1 and Public Clarification CTP003. Note the FTA guide remains at its August 2023 version and still shows the superseded 2026 sunset \u2014 for the end date, the amending decision governs. General information on published law, not advice on your own position."),React.createElement("div",{style:{marginTop:28,borderTop:"1px solid var(--aa-rule)",paddingTop:20}},React.createElement("div",{className:"eyebrow eyebrow--charcoal",style:{marginBottom:12}},"Related"),React.createElement("ul",{style:{margin:0,paddingLeft:0,listStyle:"none",display:"grid",gap:8,fontSize:15}},React.createElement("li",null,g("small-business-relief-extended-2029","What changed: relief extended to 2029 \u2192")),React.createElement("li",null,l("service-ct-filing","Corporate Tax return filing \u2192")),React.createElement("li",null,l("service-bookkeeping","Outsourced bookkeeping \u2192")))))}return f}(window.AAArticleBodies=window.AAArticleBodies||{})["small-business-relief-evidence-test"]=function(e){return n||(n=c()),n(e)}})();
